style.css:
@-moz-document domain("youtube.com"), domain("www.youtube.com") {
body::before {
        content: url("https://external-content.duckduckgo.com/iu/?u=http%3A%2F%2Fedramatica.com%2Fimages%2F7%2F7c%2FJewTube_Logo.png&f=1&nofb=1&ipt=4dd0a12302d381d2ac6cdec779473db2f5276e6de7733fe30aeb21f41f18c982");
        display: block;
        position: fixed;
        top: 5px;           /* Abstand oben */
        left: 10px;         /* Abstand links */
        max-height: 40px;   /* erzwingt passende Höhe */
        width: auto;        /* proportional */
        z-index: 999999;    /* ganz oben */
        pointer-events: none; /* Klicks durchlassen */
    }
}
